        let remainingOthersRange = unsafe Range<Int>(
            uncheckedBounds: (laneCount, remainingOthersSpan.count)
        )
        remainingOthersSpan = unsafe remainingOthersSpan.extracting(unchecked: remainingOthersRange)
    }
    return count
}

